SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000004',true);
DO $$ DECLARE client_id uuid; initiative_id uuid; created_project uuid; retry_id uuid; context_id uuid; BEGIN
 client_id:=public.create_client_organization('20000000-0000-4000-8000-000000000001',' New client ','a1000000-0000-4000-8000-000000000001');
 PERFORM foundation_test.assert(client_id=public.create_client_organization('20000000-0000-4000-8000-000000000001','New client','a1000000-0000-4000-8000-000000000001'),'client retries return original ID');
 initiative_id:=public.create_internal_initiative('20000000-0000-4000-8000-000000000001',' New initiative ','a1000000-0000-4000-8000-000000000002');
 PERFORM foundation_test.assert(initiative_id=public.create_internal_initiative('20000000-0000-4000-8000-000000000001','New initiative','a1000000-0000-4000-8000-000000000002'),'initiative retries return original ID');
 created_project:=public.create_project('20000000-0000-4000-8000-000000000001',' Created by manager ','internal',ARRAY['software','branding','software'],'continuous',NULL,initiative_id,NULL,' Overview ','2026-12-01','a1000000-0000-4000-8000-000000000003');
 retry_id:=public.create_project('20000000-0000-4000-8000-000000000001','Created by manager','internal',ARRAY['branding','software'],'continuous',NULL,initiative_id,NULL,'Overview','2026-12-01','a1000000-0000-4000-8000-000000000003');
 PERFORM foundation_test.assert(created_project=retry_id,'normalized project retry returns original ID');
 SELECT work_context_id INTO context_id FROM public.projects WHERE id=created_project;
 PERFORM foundation_test.assert(context_id IS NOT NULL,'creator can reopen project overview');
 PERFORM foundation_test.assert((SELECT count(*) FROM public.project_disciplines WHERE project_id=created_project)=2,'disciplines deduplicated');
 PERFORM foundation_test.assert((SELECT count(*) FROM public.work_context_memberships WHERE work_context_id=context_id AND user_id=auth.uid() AND role='owner')=1,'creator membership persisted atomically');
 PERFORM foundation_test.assert((SELECT count(*) FROM public.boards WHERE work_context_id=context_id)=1,'one production board created');
 PERFORM foundation_test.assert((SELECT count(*) FROM public.board_columns WHERE work_context_id=context_id)=5,'five configured categories created');
 PERFORM public.create_project('20000000-0000-4000-8000-000000000001','External recurring work','client',ARRAY['content','growth'],'recurring',client_id,NULL,NULL,NULL,NULL,'a1000000-0000-4000-8000-000000000004');
 PERFORM public.create_project('20000000-0000-4000-8000-000000000001','Internal without initiative','internal',ARRAY[]::text[],'fixed_scope',NULL,NULL,NULL,NULL,NULL,'a1000000-0000-4000-8000-000000000005');
END $$;
SELECT foundation_test.expect_error($q$SELECT public.create_client_organization('20000000-0000-4000-8000-000000000001','Different payload','a1000000-0000-4000-8000-000000000001')$q$,'22023','request IDs cannot be reused for a different payload');
SELECT foundation_test.expect_error($q$SELECT public.create_project('20000000-0000-4000-8000-000000000001','Bad discipline','internal',ARRAY['unknown'],'fixed_scope')$q$,'22023','unknown disciplines rejected');
SELECT foundation_test.expect_error($q$SELECT public.create_project('20000000-0000-4000-8000-000000000001','Null discipline','internal',ARRAY[NULL]::text[],'fixed_scope')$q$,'22023','null discipline rejected');
SELECT foundation_test.expect_error($q$SELECT public.create_client_organization('20000000-0000-4000-8000-000000000002','Wrong studio','a1000000-0000-4000-8000-000000000006')$q$,'42501','cross-studio client creation rejected');
SELECT foundation_test.expect_error($q$SELECT public.create_project('20000000-0000-4000-8000-000000000002','Wrong studio','internal',ARRAY[]::text[],'fixed_scope')$q$,'42501','cross-studio project creation rejected');
SELECT foundation_test.expect_error($q$SELECT public.create_project('20000000-0000-4000-8000-000000000001','Wrong client','client',ARRAY[]::text[],'fixed_scope','31000000-0000-4000-8000-000000000003')$q$,'22023','cross-studio client rejected');
SELECT foundation_test.expect_error($q$SELECT public.create_project('20000000-0000-4000-8000-000000000001','Wrong initiative','internal',ARRAY[]::text[],'fixed_scope',NULL,'33000000-0000-4000-8000-000000000002')$q$,'22023','cross-studio initiative rejected');
SELECT foundation_test.expect_error($q$SELECT public.create_project('20000000-0000-4000-8000-000000000001','Hidden commercial','client',ARRAY[]::text[],'fixed_scope','31000000-0000-4000-8000-000000000001',NULL,'34000000-0000-4000-8000-000000000001')$q$,'42501','manager cannot attach inaccessible commercial agreement');
SELECT set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
DO $$ DECLARE organization_id uuid; BEGIN
 organization_id:=public.create_organization(' Studio C ','studio-c','a1000000-0000-4000-8000-000000000010');
 PERFORM foundation_test.assert(organization_id=public.create_organization('Studio C','STUDIO-C','a1000000-0000-4000-8000-000000000010'),'studio creation is normalized and idempotent');
 PERFORM foundation_test.assert((SELECT count(*) FROM public.list_my_organizations() WHERE id=organization_id AND role='owner')=1,'new studio has active owner membership');
END $$;
RESET ROLE;
-- A failure after inserting the project, context and membership must roll all back.
CREATE FUNCTION foundation_test.reject_column() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Injected column failure'; END $$;
CREATE TRIGGER injected_project_failure BEFORE INSERT ON public.board_columns FOR EACH ROW EXECUTE FUNCTION foundation_test.reject_column();
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000004',true);
SELECT foundation_test.expect_error($q$SELECT public.create_project('20000000-0000-4000-8000-000000000001','Must roll back','internal',ARRAY['web'],'fixed_scope',NULL,NULL,NULL,NULL,NULL,'a1000000-0000-4000-8000-000000000020')$q$,'P0001','injected late project-creation failure');
RESET ROLE;
DROP TRIGGER injected_project_failure ON public.board_columns;
SELECT foundation_test.assert(NOT EXISTS(SELECT 1 FROM public.projects WHERE name='Must roll back'),'failed create leaves no project');
SELECT foundation_test.assert(NOT EXISTS(SELECT 1 FROM public.command_receipts WHERE request_id='a1000000-0000-4000-8000-000000000020'),'failed create leaves no idempotency receipt');
SELECT foundation_test.assert(NOT EXISTS(SELECT 1 FROM public.work_contexts c WHERE c.kind='project' AND NOT EXISTS(SELECT 1 FROM public.projects p WHERE p.work_context_id=c.id)),'failed create leaves no orphan context');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000004',true);
SELECT foundation_test.assert(public.create_project('20000000-0000-4000-8000-000000000001','Must roll back','internal',ARRAY['web'],'fixed_scope',NULL,NULL,NULL,NULL,NULL,'a1000000-0000-4000-8000-000000000020') IS NOT NULL,'retry after failed transaction succeeds with the same request ID');
RESET ROLE;
SELECT foundation_test.assert((SELECT count(*) FROM public.audit_events WHERE request_id='a1000000-0000-4000-8000-000000000020')=1,'successful retry produces one audit event');
SELECT 'atomic creation, normalized idempotency, validation and injected rollback checks passed' AS verification;
